USE sacramental_registry;

-- DROP TABLE registry;

CREATE TABLE registry (
  id INT PRIMARY KEY NOT NULL AUTO_INCREMENT,
  first_name VARCHAR(255) NOT NULL,
  last_name VARCHAR(255) NOT NULL,
  sex ENUM('Female', 'Male') NOT NULL,
  birthdate DATE,
  birth_city VARCHAR(255) NOT NULL,
  father VARCHAR(255),
  mother VARCHAR(255),
  home_address_line_1 VARCHAR(255) NOT NULL,
  home_address_line_2 VARCHAR(255),
  city VARCHAR(255) NOT NULL,
  region CHAR(2) NOT NULL,
  zip_code VARCHAR(10) NOT NULL,
  baptism DATE,
  baptism_church VARCHAR(255),
  communion DATE,
  confirmation DATE,
  wedding DATE,
  profession_of_faith DATE,
  death DATE,
  baptism_key INT,
  communion_key INT,
  confirmation_key INT,
  wedding_key INT,
  profession_of_faith_key INT,
  death_key INT,
  comments TEXT,
  date_entered DATETIME DEFAULT current_timestamp()
) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

